#!/usr/bin/env bash
# СУДИТ: scripts/knowledge-instrument-audit.sh
# probe_D1290 — в разделе «уровень не помог» прибора «знание → инструмент» нет просроченных: у знания-гейта, которое было
# уместно и не применено, нарушения прекратились либо записан `instrument_verdict` с доводом. Повод — 10 ноября 2026: три
# гейта стоят в разделе 61 день (`pattern-shell-portability` — 24 нарушения), и прибор неделями отвечает 1 (корень R5).
# Красная (1), пока в разделе есть «⏰»; 2 — нет базы или прибор не ответил (код ≥ 2 либо нет итога).
# Положительный контроль (D1295, 15 ноября 2026): прибор обязан назвать итогом «хранится N» с N > 0. Молчащий прибор
#   (выпотрошенный, упавший до печати) не пишет и раздела, и пустой раздел читался «просроченных нет».
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
L="${LESSONS_DIR:-$HOME/.claude/global-lessons}"
[ -d "$L" ] && [ -f "$R/scripts/knowledge-instrument-audit.sh" ] && [ -f "$R/hooks/frame-control-lib.sh" ] || exit 2
. "$R/hooks/frame-control-lib.sh"
O=$(mktemp "${TMPDIR:-/tmp}/probe-D1290.XXXXXX") || exit 2   # отчёт прибора — не в живое состояние
out=$(LESSONS_DIR="$L" KIA_OUTPUT="$O" bash "$R/scripts/knowledge-instrument-audit.sh" 2>/dev/null)
rc=$?
sec=$(awk '/^## Уровень не помог/{f=1; next} /^## /{f=0} f' "$O")
rm -f "$O"
[ "$rc" -ge 2 ] && exit 2
n=$(printf '%s\n' "$out" | sed -n 's/^знание → инструмент: хранится \([0-9][0-9]*\),.*/\1/p' | head -1)
frame_require_nonempty "$n" "знаний у прибора «знание → инструмент»" "итог «хранится N» в выводе прибора" || exit $?
# Раздела нет — пустой раздел прибор не печатает: это «просроченных нет», а не сломанная рамка (её судит код ≥ 2).
if grep -q '⏰' <<< "$sec"; then
    grep '⏰' <<< "$sec" | sed -E 's/^\| ([0-9]+) \| ([^|]*)\| `([^`]*)`.*/  \3: нарушений \1, в разделе \2/'
    exit 1
fi
exit 0
